"""Shared, dependency-free helpers for the incident-record prototype."""

from __future__ import annotations

from datetime import datetime
from pathlib import Path
import json
from typing import Any


def load_json(path: str | Path) -> Any:
    """Load UTF-8 JSON with a path-specific error for malformed input."""
    source = Path(path)
    try:
        with source.open("r", encoding="utf-8") as handle:
            return json.load(handle)
    except json.JSONDecodeError as exc:
        raise ValueError(f"{source}: invalid JSON at line {exc.lineno}: {exc.msg}") from exc


def parse_timestamp(value: str) -> datetime:
    """Parse an ISO-8601 timestamp and require an explicit UTC offset."""
    if not isinstance(value, str) or not value:
        raise ValueError("timestamp must be a non-empty string")
    normalised = value[:-1] + "+00:00" if value.endswith(("Z", "z")) else value
    try:
        parsed = datetime.fromisoformat(normalised)
    except ValueError as exc:
        raise ValueError(f"invalid ISO-8601 timestamp: {value!r}") from exc
    if parsed.utcoffset() is None:
        raise ValueError(f"timestamp must include a timezone offset: {value!r}")
    return parsed


def isoformat_z(value: datetime) -> str:
    """Return a stable ISO string; retain the supplied offset rather than guessing."""
    rendered = value.isoformat(timespec="seconds")
    return rendered[:-6] + "Z" if rendered.endswith("+00:00") else rendered


def get_path(record: Any, dotted_path: str) -> tuple[bool, Any]:
    """Return (present, value); absent and an explicitly present null differ."""
    current = record
    for part in dotted_path.split("."):
        if not isinstance(current, dict) or part not in current:
            return False, None
        current = current[part]
    return True, current

#!/usr/bin/env python3
"""Lightweight consistency checks; not a replacement for JSON Schema validation."""

from __future__ import annotations

import argparse
from pathlib import Path
import sys
from typing import Any

from common import load_json, parse_timestamp


REQUIRED_TOP_LEVEL = {
    "id", "schema_version", "record_status", "synthetic", "title", "summary",
    "case_type", "sources", "system", "setting", "timeline", "event",
    "causation", "remediation", "reporting", "uncertainty", "relationships",
    "provenance", "privacy",
}


def validate_record(record: Any) -> list[str]:
    """Return human-readable errors. An empty list means these checks passed."""
    errors: list[str] = []
    if not isinstance(record, dict):
        return ["top-level JSON value must be an object"]

    missing = sorted(REQUIRED_TOP_LEVEL - record.keys())
    if missing:
        errors.append("missing top-level fields: " + ", ".join(missing))

    record_id = record.get("id")
    synthetic = record.get("synthetic")
    title = record.get("title")
    summary = record.get("summary")
    sources = record.get("sources")

    if record.get("schema_version") != "0.1.0":
        errors.append("schema_version must be '0.1.0'")
    if not isinstance(record_id, str) or not record_id:
        errors.append("id must be a non-empty string")
    if not isinstance(synthetic, bool):
        errors.append("synthetic must be a boolean")

    if synthetic is True:
        if not isinstance(record_id, str) or not record_id.startswith("SYN-"):
            errors.append("synthetic record id must start with SYN-")
        if not isinstance(title, str) or not title.startswith("SYNTHETIC"):
            errors.append("synthetic title must start with SYNTHETIC")
        if not isinstance(summary, str) or not summary.startswith("SYNTHETIC"):
            errors.append("synthetic summary must start with SYNTHETIC")
        if sources != []:
            errors.append("synthetic records must have an empty sources array")
    elif synthetic is False:
        if not isinstance(record_id, str) or not record_id.startswith("PUB-"):
            errors.append("public record id must start with PUB-")
        if not isinstance(sources, list) or not sources:
            errors.append("public records require at least one source")
        else:
            for index, source in enumerate(sources):
                if not isinstance(source, dict):
                    errors.append(f"sources[{index}] must be an object")
                    continue
                for key in ("url", "title", "publisher", "retrieved_at", "source_type", "supports"):
                    if not source.get(key):
                        errors.append(f"sources[{index}].{key} is required")
                if source.get("url") and not str(source["url"]).startswith("https://"):
                    errors.append(f"sources[{index}].url must use HTTPS")

    timeline = record.get("timeline")
    if isinstance(timeline, dict):
        for key in ("occurred_start", "occurred_end", "first_aware_at", "reported_at"):
            value = timeline.get(key)
            if value is not None:
                try:
                    parse_timestamp(value)
                except ValueError as exc:
                    errors.append(f"timeline.{key}: {exc}")
        try:
            start = timeline.get("occurred_start")
            end = timeline.get("occurred_end")
            if start is not None and end is not None and parse_timestamp(start) > parse_timestamp(end):
                errors.append("timeline.occurred_start must not be after occurred_end")
        except ValueError:
            pass  # The individual timestamp error above is more useful.

    event = record.get("event")
    if isinstance(event, dict):
        harm = event.get("harm")
        if isinstance(harm, dict):
            occurred = harm.get("occurred")
            categories = harm.get("categories")
            severity = harm.get("severity")
            if occurred not in (True, False, None):
                errors.append("event.harm.occurred must be true, false, or null")
            if not isinstance(categories, list):
                errors.append("event.harm.categories must be an array")
                categories = []
            if occurred is True:
                if severity in ("none", "unknown"):
                    errors.append("observed harm cannot have severity 'none' or 'unknown'")
                if not categories:
                    errors.append("observed harm requires at least one harm category")
            elif occurred is False:
                if categories:
                    errors.append("harm categories must be empty when harm did not occur")
                if severity != "none":
                    errors.append("severity must be 'none' when harm did not occur")
            elif occurred is None and severity != "unknown":
                errors.append("severity must be 'unknown' when harm occurrence is unknown")
        counterfactual = event.get("counterfactual")
        if record.get("case_type") == "near_miss" and isinstance(counterfactual, dict):
            if not counterfactual.get("plausible_outcome"):
                errors.append("near miss requires a plausible outcome")
            if not counterfactual.get("basis"):
                errors.append("near miss requires a counterfactual basis")

    reporting = record.get("reporting")
    if isinstance(reporting, dict):
        hours = reporting.get("assumed_rule_deadline_hours")
        if hours is not None and (isinstance(hours, bool) or not isinstance(hours, int) or not 1 <= hours <= 720):
            errors.append("reporting.assumed_rule_deadline_hours must be null or an integer from 1 to 720")

    privacy = record.get("privacy")
    if isinstance(privacy, dict) and privacy.get("contains_sensitive_details") is True:
        errors.append("record contains sensitive details and must not enter the public-source pilot")

    return errors


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("records", nargs="+", type=Path)
    args = parser.parse_args(argv)
    failed = False
    for path in args.records:
        try:
            record = load_json(path)
            errors = validate_record(record)
        except (OSError, ValueError) as exc:
            errors = [str(exc)]
        if errors:
            failed = True
            print(f"FAIL {path}")
            for error in errors:
                print(f"  - {error}")
        else:
            print(f"OK   {path}")
    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Compute transparent per-field exact agreement for two independent annotators."""

from __future__ import annotations

import argparse
import json
import sys
from typing import Any

from common import get_path, load_json


def compare_annotations(payload: dict[str, Any]) -> dict[str, Any]:
    """Treat absent as distinct from explicit null; never fill missing values."""
    fields = payload["fields"]
    pairs = payload["pairs"]
    results: dict[str, Any] = {}
    for field in fields:
        disagreements = []
        both_present = both_missing = agreements_all = agreements_present = 0
        only_a = only_b = 0
        for pair in pairs:
            a_present, a_value = get_path(pair["annotator_a"], field)
            b_present, b_value = get_path(pair["annotator_b"], field)
            record_id = pair["record_id"]
            equal = a_present == b_present and (not a_present or a_value == b_value)
            if equal:
                agreements_all += 1
            else:
                disagreements.append({
                    "record_id": record_id,
                    "a_present": a_present,
                    "a": a_value if a_present else "<ABSENT>",
                    "b_present": b_present,
                    "b": b_value if b_present else "<ABSENT>",
                })
            if a_present and b_present:
                both_present += 1
                if a_value == b_value:
                    agreements_present += 1
            elif not a_present and not b_present:
                both_missing += 1
            elif a_present:
                only_a += 1
            else:
                only_b += 1

        count = len(pairs)
        results[field] = {
            "n_cases": count,
            "both_present": both_present,
            "both_absent": both_missing,
            "only_a_present": only_a,
            "only_b_present": only_b,
            "agreements_when_both_present": agreements_present,
            "agreement_when_both_present": (agreements_present / both_present) if both_present else None,
            "exact_agreement_all_cases_absent_equals_absent": (agreements_all / count) if count else None,
            "disagreements_or_presence_mismatches": disagreements,
        }
    return {
        "schema_version": payload.get("schema_version"),
        "method": "Per-field exact agreement; absent is distinct from null; no imputation or pooled score.",
        "n_pairs": len(pairs),
        "fields": results,
        "interpretation_warning": "Small samples and structural missingness can make percentages unstable. Inspect every disagreement.",
    }


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("input", help="JSON containing fields and annotation pairs")
    args = parser.parse_args(argv)
    try:
        result = compare_annotations(load_json(args.input))
    except (OSError, ValueError, KeyError, TypeError) as exc:
        parser.exit(2, f"error: {exc}\n")
    print(json.dumps(result, indent=2, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    sys.exit(main())

